INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',11,'{"_type":"chat:Message","id":"8641420749:26","threadId":"telegram:8641420749","text":"More info:\n• for Marseille Napoli this year, I will be with 2 friends who are less experienced than me, my goal is to have the best experience with them as possible, I''m not seeking any sort of performance or timing. I want to finish on Friday end of the day soit 230km par jour minimum et un total de 17950m de D+. I want to feel good and have no knee pain. Zero knee pain is my main objective.\n• regarding availability for training, I''m fully available from June 15 (today) to July 16.\n• between July 16 and July 24, I will be doing a hike in the Alps with 15 to 20km per day and between 1000 and 2000m de D+ per day.\n• then July 25 to Aug 9 I will be fully available for training\n• then Aug 10 to 19 also available but maybe less hours per day (not sure yet if I''ll have my bike or another bike, I''ll be on vacation in Annecy)\n• then Aug 20 to Sept 27 fully available\n• Marseill Napoli starts on Sunday Sept 27","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"More info:\n• for Marseille Napoli this year, I will be with 2 friends who are less experienced than me, my goal is to have the best experience with them as possible, I''m not seeking any sort of performance or timing. I want to finish on Friday end of the day soit 230km par jour minimum et un total de 17950m de D+. I want to feel good and have no knee pain. Zero knee pain is my main objective.\n• regarding availability for training, I''m fully available from June 15 (today) to July 16.\n• between July 16 and July 24, I will be doing a hike in the Alps with 15 to 20km per day and between 1000 and 2000m de D+ per day.\n• then July 25 to Aug 9 I will be fully available for training\n• then Aug 10 to 19 also available but maybe less hours per day (not sure yet if I''ll have my bike or another bike, I''ll be on vacation in Annecy)\n• then Aug 20 to Sept 27 fully available\n• Marseill Napoli starts on Sunday Sept 27","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":8,"column":43,"offset":913}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":8,"column":43,"offset":913}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":8,"column":43,"offset":913}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-15T21:00:50.000Z","edited":false},"attachments":[],"isMention":false}',1782162048320);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',12,'{"_type":"chat:Message","id":"8641420749:30","threadId":"telegram:8641420749","text":"See attached my history from TrainingPeaks with planned and actual sessions from my coach in July/Aug/Sept 2025, then I stopped being coach by him until Jan 2026 and then I stopped again around April","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"See attached my history from TrainingPeaks with planned and actual sessions from my coach in July/Aug/Sept 2025, then I stopped being coach by him until Jan 2026 and then I stopped again around April","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":200,"offset":199}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":200,"offset":199}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":200,"offset":199}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-15T21:11:21.000Z","edited":false},"attachments":[{"type":"file","name":"workouts.csv","mimeType":"text/csv","size":32508}],"isMention":false}',1782162679193);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',13,'{"_type":"chat:Message","id":"8641420749:35","threadId":"telegram:8641420749","text":"Quelques commentaires : \n• explique moi mieux ce qu''est le TSS\n• tu me dis que le pacing M-N etait trop agressif mais regarde le profil d''elevation de ces activités Strava : beaucoup trop d''accumulés pour rester en Z2 80% du temps. A l''inverse, Porto Lisboa c''etait completement plat. Pareil pour Cascais le 3 juin.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Quelques commentaires :\n• explique moi mieux ce qu''est le TSS\n• tu me dis que le pacing M-N etait trop agressif mais regarde le profil d''elevation de ces activités Strava : beaucoup trop d''accumulés pour rester en Z2 80% du temps. A l''inverse, Porto Lisboa c''etait completement plat. Pareil pour Cascais le 3 juin.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":253,"offset":315}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":253,"offset":315}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":253,"offset":315}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-15T21:42:39.000Z","edited":false},"attachments":[],"isMention":false}',1782164556102);
