INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',15,'{"_type":"chat:Message","id":"8641420749:41","threadId":"telegram:8641420749","text":"En ce qui concerne les exercices de renfo que je fais a la maison : \n1. Contralateral plank (3x20-30sec each side)\n2. SL brige 45° (2x20-30sec each side)\n3. SL bridge 20° (2x10-20sec each side)\n4. side plank with leg raise and feet on bench (2x10sec each side)\nand to others for which I will send you videos","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"En ce qui concerne les exercices de renfo que je fais a la maison :","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":68,"offset":67}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":69,"offset":68}}},{"type":"list","ordered":true,"start":1,"spread":false,"children":[{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"Contralateral plank (3x20-30sec each side)","position":{"start":{"line":2,"column":4,"offset":72},"end":{"line":2,"column":46,"offset":114}}}],"position":{"start":{"line":2,"column":4,"offset":72},"end":{"line":2,"column":46,"offset":114}}}],"position":{"start":{"line":2,"column":1,"offset":69},"end":{"line":2,"column":46,"offset":114}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"SL brige 45° (2x20-30sec each side)","position":{"start":{"line":3,"column":4,"offset":118},"end":{"line":3,"column":39,"offset":153}}}],"position":{"start":{"line":3,"column":4,"offset":118},"end":{"line":3,"column":39,"offset":153}}}],"position":{"start":{"line":3,"column":1,"offset":115},"end":{"line":3,"column":39,"offset":153}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"SL bridge 20° (2x10-20sec each side)","position":{"start":{"line":4,"column":4,"offset":157},"end":{"line":4,"column":40,"offset":193}}}],"position":{"start":{"line":4,"column":4,"offset":157},"end":{"line":4,"column":40,"offset":193}}}],"position":{"start":{"line":4,"column":1,"offset":154},"end":{"line":4,"column":40,"offset":193}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"side plank with leg raise and feet on bench (2x10sec each side)\nand to others for which I will send you videos","position":{"start":{"line":5,"column":4,"offset":197},"end":{"line":6,"column":47,"offset":307}}}],"position":{"start":{"line":5,"column":4,"offset":197},"end":{"line":6,"column":47,"offset":307}}}],"position":{"start":{"line":5,"column":1,"offset":194},"end":{"line":6,"column":47,"offset":307}}}],"position":{"start":{"line":2,"column":1,"offset":69},"end":{"line":6,"column":47,"offset":307}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":6,"column":47,"offset":307}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-15T21:55:47.000Z","edited":false},"attachments":[],"isMention":false}',1782165347407);
