INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',27,'{"_type":"chat:Message","id":"8641420749:72","threadId":"telegram:8641420749","text":"En ce qui concerne le macro plan, pour la phase de récupération, je vais faire du renforcement trois fois par semaine.\n\nRéalistiquement je ferais de la natation que une à deux fois par semaine, jamais trois, ce n''est pas réaliste.\n\nPour le vélo, ça m''étonne un peu que je refasse du vélo aussi vite. Je me demandais s''il ne fallait pas complètement arrêter mais tu sais ça mieux que moi. Peut-être une à deux sorties par semaine plutôt que deux à trois sorties par semaine, qu''est-ce que tu en penses ?\n\nPour la phase de randonnée des Alpes, je ne ferai pas de renfort cette semaine-là, j''aurai pas le temps.\n\nPour la phase à Annecy, ça me paraît irréaliste de faire autant. Ce sera certainement moins, mais peut-être plus de courses à pied que de vélo","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"En ce qui concerne le macro plan, pour la phase de récupération, je vais faire du renforcement trois fois par semaine.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":119,"offset":118}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":119,"offset":118}}},{"type":"paragraph","children":[{"type":"text","value":"Réalistiquement je ferais de la natation que une à deux fois par semaine, jamais trois, ce n''est pas réaliste.","position":{"start":{"line":3,"column":1,"offset":120},"end":{"line":3,"column":111,"offset":230}}}],"position":{"start":{"line":3,"column":1,"offset":120},"end":{"line":3,"column":111,"offset":230}}},{"type":"paragraph","children":[{"type":"text","value":"Pour le vélo, ça m''étonne un peu que je refasse du vélo aussi vite. Je me demandais s''il ne fallait pas complètement arrêter mais tu sais ça mieux que moi. Peut-être une à deux sorties par semaine plutôt que deux à trois sorties par semaine, qu''est-ce que tu en penses ?","position":{"start":{"line":5,"column":1,"offset":232},"end":{"line":5,"column":271,"offset":502}}}],"position":{"start":{"line":5,"column":1,"offset":232},"end":{"line":5,"column":271,"offset":502}}},{"type":"paragraph","children":[{"type":"text","value":"Pour la phase de randonnée des Alpes, je ne ferai pas de renfort cette semaine-là, j''aurai pas le temps.","position":{"start":{"line":7,"column":1,"offset":504},"end":{"line":7,"column":105,"offset":608}}}],"position":{"start":{"line":7,"column":1,"offset":504},"end":{"line":7,"column":105,"offset":608}}},{"type":"paragraph","children":[{"type":"text","value":"Pour la phase à Annecy, ça me paraît irréaliste de faire autant. Ce sera certainement moins, mais peut-être plus de courses à pied que de vélo","position":{"start":{"line":9,"column":1,"offset":610},"end":{"line":9,"column":143,"offset":752}}}],"position":{"start":{"line":9,"column":1,"offset":610},"end":{"line":9,"column":143,"offset":752}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":9,"column":143,"offset":752}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-16T08:56:44.000Z","edited":false},"attachments":[],"isMention":false}',1782205004569);
